def spins(lang):
 s=F.start(320)
 def mag(x,y,ang):
  import math
  dx,dy=22*math.cos(math.radians(ang)),22*math.sin(math.radians(ang))
  return f'<circle cx="{x}" cy="{y}" r="16" fill="none" stroke="#222" stroke-width="1.5"/>'+line(x-dx,y-dy,x+dx,y+dy,1.5)+f'<path d="M{x+dx} {y+dy} l{-dx*0.3-dy*0.2} {-dy*0.3+dx*0.2} l{dy*0.4} {-dx*0.4} Z" fill="#222"/>'
 for (x,y,a) in ((90,60,-60),(200,100,-110),(70,170,-100),(160,230,60),(240,190,-130),(130,150,180)):s+=mag(x,y,a)
 s+=line(300,150,560,60,1.2,'#555','stroke-dasharray="3 3"')+line(300,150,560,240,1.2,'#555','stroke-dasharray="3 3"')
 s+=mag(610,50,90)+mag(610,240,-90)+t(690,50,K(lang,'β spin','β سپن','β سپین'),12)+t(690,72,K(lang,'higher energy','زیادہ توانائی','لوړه انرژي'),11)+t(690,240,K(lang,'α spin','α سپن','α سپین'),12)+t(690,262,K(lang,'lower energy','کم توانائی','ټیټه انرژي'),11)
 s+=line(540,220,540,80,2,'#c62828')+'<path d="M534 90 L540 76 L546 90 Z" fill="#c62828"/>'+t(515,150,'ΔE',13)
 s+='<path d="M790 280 L790 60 L775 60 L800 30 L825 60 L810 60 L810 280 Z" fill="#43a047"/>'+t(830,150,'B₀',13)+t(760,300,K(lang,'External field','بیرونی میدان','بهرنۍ ساحه'),11,'#2e7d32')
 s+=t(150,280,K(lang,'No field','کوئی میدان نہیں','ساحه نشته'),12,'#1a237e')+t(150,296,K(lang,'spins in all directions','ہر سمت میں سپن','په ټولو لوریو سپین'),11)+t(150,310,K(lang,'no energy difference','توانائی کا کوئی فرق نہیں','د انرژۍ توپیر نشته'),11)
 s+=F.arrow(330,480,280,K(lang,'B₀ increases','B₀ بڑھتا ہے','B₀ زیاتېږي'))+t(640,296,K(lang,'Magnetic field','مقناطیسی میدان','مقناطیسي ساحه'),12,'#1a237e')+t(640,312,K(lang,'spins aligned with the field (α) or against the field (β)','سپن میدان کے ساتھ (α) یا خلاف (β)','سپین له ساحې سره (α) یا ضد (β)'),10)
 return s.replace('viewBox="0 0 850 320"','viewBox="0 0 850 320"')+'</svg>'

